-- Repair only metadata introduced by the initial order grants; preserve grant ownership and all existing business data.
UPDATE Permission SET createdAt=NOW(3),updatedAt=NOW(3) WHERE code IN ('orders.create','orders.edit','orders.cancel','shop.orders.read','shop.orders.create','shop.orders.edit','shop.orders.cancel') AND (CAST(createdAt AS CHAR) LIKE '0000%' OR CAST(updatedAt AS CHAR) LIKE '0000%');
UPDATE RolePermission rp JOIN Permission p ON p.id=rp.permissionId SET rp.id=IF(rp.id='',UUID(),rp.id),rp.createdAt=NOW(3),rp.updatedAt=NOW(3) WHERE p.code IN ('orders.read','orders.create','orders.edit','orders.cancel','shop.orders.read','shop.orders.create','shop.orders.edit','shop.orders.cancel') AND (rp.id='' OR CAST(rp.createdAt AS CHAR) LIKE '0000%' OR CAST(rp.updatedAt AS CHAR) LIKE '0000%');
